#!/usr/bin/env python3
"""deploy/k8s/base (generated by tools/gen/gen_k8s.py from the compose model): fresh, every reference resolves (volumes, claims, secrets, selectors, ports, peer URIs of every configuration to a
Service), the pods are restricted except for what the UPF needs, the compose addresses are rendered when the pod starts (the init scripts are RUN here with a fake getent), no `latest` image."""
import os
import re
import subprocess
import sys
import tempfile
from pathlib import Path

try:
    import yaml
except ImportError:
    print("SKIP: PyYAML is not installed")
    sys.exit(77)

ROOT = Path(__file__).resolve().parent.parent.parent
BASE = ROOT / "deploy" / "k8s" / "base"


def main():
    ok = True

    def check(name, cond, got=""):
        nonlocal ok
        print(("PASS  " if cond else "FAIL  ") + name + ("" if cond else "  -> " + repr(got)))
        ok = ok and cond

    p = subprocess.run([sys.executable, str(ROOT / "tools" / "gen" / "gen_k8s.py"), "--check"], capture_output=True, text=True)
    check("the manifests are in step with the compose model", p.returncode == 0, p.stdout + p.stderr)
    docs = []
    for f in sorted(BASE.glob("*.yaml")):
        for d in yaml.safe_load_all(f.read_text(encoding="utf-8")):
            if d:
                docs.append((f.name, d))
    by = lambda kind: [d for _, d in docs if d["kind"] == kind]
    nfs = sorted(d["metadata"]["name"] for d in by("Deployment"))
    check("twelve functions, each with a Deployment, a Service and a ConfigMap", len(nfs) == 12 and sorted(d["metadata"]["name"] for d in by("Service")) == nfs
          and sorted(d["metadata"]["name"] for d in by("ConfigMap")) == [n + "-config" for n in nfs], nfs)
    kust = [d for _, d in docs if d["kind"] == "Kustomization"][0]
    check("the kustomization lists every file", set(kust["resources"]) == {f.name for f in BASE.glob("*.yaml") if f.name != "kustomization.yaml"}, kust["resources"])
    check("every object is in the namespace g5c", all(d["metadata"].get("namespace") == "g5c" for d in by("Deployment") + by("Service") + by("ConfigMap") + by("PersistentVolumeClaim") + by("NetworkPolicy")))

    cms = {d["metadata"]["name"] for d in by("ConfigMap")}
    pvcs = {d["metadata"]["name"] for d in by("PersistentVolumeClaim")}
    svc = {d["metadata"]["name"]: d for d in by("Service")}
    problems = []
    for d in by("Deployment"):
        nf = d["metadata"]["name"]
        spec = d["spec"]["template"]["spec"]
        labels = d["spec"]["template"]["metadata"]["labels"]
        if d["spec"]["selector"]["matchLabels"].items() > labels.items():
            problems.append("%s: selector does not match the pod" % nf)
        vols = {v["name"]: v for v in spec["volumes"]}
        for c in spec["containers"] + spec.get("initContainers", []):
            for m in c.get("volumeMounts", []):
                if m["name"] not in vols:
                    problems.append("%s: mount %s has no volume" % (nf, m["name"]))
            if ":latest" in c["image"] or ":" not in c["image"]:
                problems.append("%s: image %s is not pinned" % (nf, c["image"]))
        for v in vols.values():
            if "configMap" in v and v["configMap"]["name"] not in cms:
                problems.append("%s: ConfigMap %s missing" % (nf, v["configMap"]["name"]))
            if "persistentVolumeClaim" in v and v["persistentVolumeClaim"]["claimName"] not in pvcs:
                problems.append("%s: claim missing" % nf)
        # the Service selects the pod and exposes ports the container has
        cont = spec["containers"][0]
        cports = {(p["name"], p["protocol"], p["containerPort"]) for p in cont["ports"]}
        s = svc.get(nf)
        if s is None or s["spec"]["selector"] != d["spec"]["selector"]["matchLabels"]:
            problems.append("%s: no Service selecting it" % nf)
        else:
            for sp in s["spec"]["ports"]:
                if not any(c[0] == sp["targetPort"] and c[1] == sp["protocol"] for c in cports):
                    problems.append("%s: Service port %s does not reach a container port" % (nf, sp["name"]))
        # probes use a port the container has
        for probe in ("livenessProbe", "readinessProbe"):
            port = (cont[probe].get("tcpSocket") or cont[probe].get("httpGet"))["port"]
            if port not in {c[0] for c in cports}:
                problems.append("%s: %s on an unknown port" % (nf, probe))
        # pod security: restricted, except the capability the UPF needs
        sc = cont["securityContext"]
        if not (sc["runAsNonRoot"] and sc["readOnlyRootFilesystem"] and not sc["allowPrivilegeEscalation"] and sc["capabilities"]["drop"] == ["ALL"] and sc["seccompProfile"]["type"] == "RuntimeDefault"):
            problems.append("%s: container security context is not restricted" % nf)
        if nf != "upf" and "add" in sc["capabilities"]:
            problems.append("%s: adds a capability" % nf)
        if spec.get("automountServiceAccountToken") is not False or not spec["securityContext"]["runAsNonRoot"]:
            problems.append("%s: pod security context" % nf)
    check("volumes, claims, selectors, ports, probes, images and the security context are all consistent", not problems, problems)
    upf = [d for d in by("Deployment") if d["metadata"]["name"] == "upf"][0]["spec"]["template"]["spec"]
    check("the UPF alone has NET_ADMIN and the TUN device", upf["containers"][0]["securityContext"]["capabilities"]["add"] == ["NET_ADMIN"] and any(v.get("hostPath", {}).get("path") == "/dev/net/tun" for v in upf["volumes"]))
    amf = svc["amf"]["spec"]["ports"]
    check("N2 is an SCTP port of the AMF, N3 and N4 are UDP ports of the UPF", any(p["port"] == 38412 and p["protocol"] == "SCTP" for p in amf)
          and {(p["port"], p["protocol"]) for p in svc["upf"]["spec"]["ports"]} >= {(2152, "UDP"), (8805, "UDP")})

    # every peer a configuration names is a Service of the right port
    bad = []
    for cm in by("ConfigMap"):
        text = list(cm["data"].values())[0]
        for host, port in re.findall(r"https?://([a-z][a-z0-9-]*):(\d+)", text):
            if host not in svc or int(port) not in {p["port"] for p in svc[host]["spec"]["ports"]}:
                bad.append((cm["metadata"]["name"], host, port))
    check("every peer URI in every configuration is a Service with that port", not bad, bad)

    # secrets: every key a pod mounts is one of the files gen-secrets.sh makes
    gen = (ROOT / "deploy" / "compose" / "gen-secrets.sh").read_text()
    keys = {i["key"] for d in by("Deployment") for v in d["spec"]["template"]["spec"]["volumes"] if "secret" in v for i in v["secret"]["items"]}
    missing = [k for k in keys if k not in gen and not k.endswith(".token") and not k.endswith(".key")]
    check("secrets come from one Secret, g5c-secrets, which the operator creates (none is generated here)", keys and not any(d["kind"] == "Secret" for _, d in docs) and not missing, (keys, missing))

    # the addresses of the compose network are rendered at pod start: run the init scripts
    rendered = 0
    problems = []
    for d in by("Deployment"):
        spec = d["spec"]["template"]["spec"]
        nf = d["metadata"]["name"]
        cm = [c for c in by("ConfigMap") if c["metadata"]["name"] == nf + "-config"][0]
        has_literal = "10.100.0." in list(cm["data"].values())[0]
        if has_literal != bool(spec.get("initContainers")):
            problems.append("%s: init container and literal addresses disagree" % nf)
        if not spec.get("initContainers"):
            continue
        script = spec["initContainers"][0]["command"][2]
        with tempfile.TemporaryDirectory() as tmp:
            tmp = Path(tmp)
            (tmp / "config-src").mkdir()
            (tmp / "rendered").mkdir()
            (tmp / "bin").mkdir()
            (tmp / "config-src" / (nf + ".yaml")).write_text(list(cm["data"].values())[0])
            (tmp / "bin" / "getent").write_text("#!/bin/sh\necho \"10.96.0.77 $2\"\n")
            (tmp / "bin" / "getent").chmod(0o755)
            sh = script.replace("/config-src", str(tmp / "config-src")).replace("/rendered", str(tmp / "rendered"))
            r = subprocess.run(["/bin/sh", "-c", sh], env={"PATH": str(tmp / "bin") + ":/usr/bin:/bin", "POD_IP": "10.244.1.5"}, capture_output=True, text=True, timeout=20)
            out = (tmp / "rendered" / (nf + ".yaml")).read_text() if (tmp / "rendered" / (nf + ".yaml")).exists() else ""
            if r.returncode != 0 or "10.100.0." in out or "10.100.0.0/24" in out:
                problems.append("%s: rendering failed or left a compose address: %s %s" % (nf, r.stderr[-120:], re.findall(r"10\.100\.0\.\d+", out)))
            if nf == "upf" and ("10.244.1.5" not in out or "10.96.0.77" in out):
                problems.append("upf: its own address must be the pod IP")
            if nf == "smf" and ("10.96.0.77" not in out or "10.244.1.5" not in out):
                problems.append("smf: its own address is the pod IP and the UPF's is the Service address")
            rendered += 1
    check("the init scripts render every compose address (own address: pod IP; a peer's: the address of its Service)", rendered >= 4 and not problems, problems)
    pols = {d["metadata"]["name"] for d in by("NetworkPolicy")}
    check("default deny, with the allowances the core needs", {"default-deny", "allow-inside-the-core", "allow-n2-from-gnbs", "allow-n3-from-gnbs"} <= pols, pols)
    print("k8s: PASS" if ok else "k8s: FAIL")
    return 0 if ok else 1


if __name__ == "__main__":
    sys.exit(main())
